    private bool _expanded;
    private bool _saving;
    private string? _message;
    private bool _isError;

    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";

    private async Task UpdatePasswordAsync()
    {
        _message = null;

        if (string.IsNullOrWhiteSpace(_currentPassword) || string.IsNullOrWhiteSpace(_newPassword))
        {
            _message = "Please fill in all password fields.";
            _isError = true;
            return;
        }

        if (_newPassword != _confirmPassword)
        {
            _message = "New password and confirmation do not match.";
            _isError = true;
            return;
        }

        _saving = true;
        try
        {
            await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
            _message = "Password updated successfully!";
            _isError = false;
            _currentPassword = "";
            _newPassword = "";
            _confirmPassword = "";
        }
        catch (Exception ex)
        {
            _message = $"Failed to update password: {ex.Message}";
            _isError = true;
        }
        _saving = false;
    }
}
"}

{"path": "/tmp/sv-7db6957378c34178a8ba6f2d77d1b23c/Components/Pages/Settings/ActiveSessionsTable.razor", "file_text": "@namespace sv_7db6957378c34178a8ba6f2d77d1b23c.Components.Pages.Settings
@using sv_7db6957378c34178a8ba6f2d77d1b23c.Services

<div class="card">
    <div class="card-header">
        <h5 class="mb-0">Active Sessions</h5>
    </div>
    <div class="card-body p-0">
        <div class="table-responsive">
            <table class="table table-hover mb-0">
                <thead>
                    <tr>
                        <th>Device</th>
                        <th>Location</th>
                        <th>Last Active</th>
                        <th></th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var session in Sessions)
                    {
                        <tr>
                            <td>@session.Device</td>
                            <td>@session.Location</td>
                            <td>@session.LastActive.ToString("g")</td>
                            <td>
                                @if (session.Id != CurrentSessionId)
                                {
                                    <button class="btn btn-sm btn-outline-danger"
                                            @onclick="() => PromptRevoke(session)">
                                        Revoke
                                    </button>
                                }
                                else
                                {
                                    <span class="badge bg-success">Current</span>
                                }
                            </td>
                        </tr>
                    }
                </tbody>
            </table>
        </div>
    </div>
</div>

@* Confirmation Dialog *@
@if (_sessionToRevoke is not null)
{
    <div class="modal d-block" tabindex="-1" style="background-color: rgba(0,0,0,0.5);">
        <div class="modal-dialog">
            <div class="modal-content">
                <div class="modal-header">
                    <h5 class="modal-title">Confirm Session Revocation</h5>
                    <button type="button" class="btn-close" @onclick="CancelRevoke"></button>
                </div>
                <div class="modal-body">
                    <p>Are you sure you want to revoke the session on <strong>@_sessionToRevoke.Device</strong> from <strong>@_sessionToRevoke.Location</strong>?</p>
                </div>
                <div class="modal-footer">
                    <button type="button" class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                    <button type="button" class="btn btn-danger" @onclick="ConfirmRevokeAsync" disabled="@_revoking">
                        @if (_revoking)
                        {
                            <span class="spinner-border spinner-border-sm me-1"></span>
                        }
                        Revoke Session
                    </button>
                </div>
            </div>
        </div>
    </div>
}

@code {
    [Parameter] public List<ActiveSession> Sessions { get; set; } = new();
    [Parameter] public string CurrentSessionId { get; set; } = "";
    [Parameter] public EventCallback<string> OnSessionRevoked { get; set; }

    private ActiveSession? _sessionToRevoke;
    private bool _revoking;

    private void PromptRevoke(ActiveSession session)
    {
        _sessionToRevoke = session;
    }

    private void CancelRevoke()
    {
        _sessionToRevoke = null;
    }

    private async Task ConfirmRevokeAsync()
    {
        if (_sessionToRevoke is null) return;
        _revoking = true;
        await OnSessionRevoked.InvokeAsync(_sessionToRevoke.Id);
        _revoking = false;
        _sessionToRevoke = null;
    }
}
"}

{"path": "/tmp/sv-7db6957378c34178a8ba6f2d77d1b23c/Components/Pages/Settings/SecuritySection.razor", "file_text": "@namespace sv_7db6957378c34178a8ba6f2d77d1b23c.Components.Pages.Settings
@using sv_7db6957378c34178a8ba6f2d77d1b23c.Services

<div class="d-flex flex-column gap-3">
    @if (_loading)
    {
        <div class="text-center py-4">
            <div class="spinner-border" role="status">
                <span class="visually-hidden">Loading...</span>
            </div>
        </div>
    }
    else
    {
        <ChangePasswordPanel SettingsService="SettingsService" />

        <div class="card mb-3">
            <div class="card-body">
                <div class="d-flex justify-content-between align-items-center">
                    <div>
                        <h5 class="mb-1">Two-Factor Authentication</h5>
                        <p class="text-muted mb-0">
                            @if (_twoFactorEnabled)
                            {
                                <span class="badge bg-success me-1">Enabled</span>
                                <text>Your account is protected with 2FA.</text>
                            }
                            else
                            {
                                <span class="badge bg-warning text-dark me-1">Disabled</span>
                                <text>Enable 2FA for extra security.</text>
                            }
                        </p>
                    </div>
                    <div class="form-check form-switch">
                        <input class="form-check-input" type="checkbox" id="twoFactor"
                               checked="@_twoFactorEnabled" @onchange="Toggle2FA" style="transform: scale(1.3);" />
                    </div>
                </div>
                @if (_lastPasswordChange.HasValue)
                {
                    <small class="text-muted mt-2 d-block">Last password change: @_lastPasswordChange.Value.ToString("f")</small>
                }
            </div>
        </div>

        <ActiveSessionsTable Sessions="_sessions"
                             CurrentSessionId="@_currentSessionId"
                             OnSessionRevoked="RevokeSessionAsync" />
    }
</div>

@code {
    [Parameter] public ISettingsService SettingsService { get; set; } = default!;

    private bool _loading = true;
    private bool _twoFactorEnabled;
    private DateTime? _lastPasswordChange;
    private List<ActiveSession> _sessions = new();
    private string _currentSessionId = "";

    protected override async Task OnInitializedAsync()
    {
        await LoadAsync();
    }

    private async Task LoadAsync()
    {
        _loading = true;
        var settings = await SettingsService.GetSecuritySettingsAsync();
        _twoFactorEnabled = settings.TwoFactorEnabled;
        _lastPasswordChange = settings.LastPasswordChange;
        _sessions = settings.Sessions;
        // Assume the first session is the current one
        _currentSessionId = _sessions.FirstOrDefault()?.Id ?? "";
        _loading = false;
    }

    private void Toggle2FA(ChangeEventArgs e)
    {
        _twoFactorEnabled = (bool)(e.Value ?? false);
    }

    private async Task RevokeSessionAsync(string sessionId)
    {
        await SettingsService.RevokeSessionAsync(sessionId);
        _sessions = _sessions.Where(s => s.Id != sessionId).ToList();
    }
}
"}

{"path": "/tmp/sv-7db6957378c34178a8ba6f2d77d1b23c/Components/Pages/Settings/AppearanceSection.razor", "file_text": "@namespace sv_7db6957378c34178a8ba6f2d77d1b23c.Components.Pages.Settings
@using sv_7db6957378c34178a8ba6f2d77d1b23c.Services

<div class="card">
    <div class="card-header">
        <h4 class="mb-0">Appearance Settings</h4>
    </div>
    <div class="card-body">
        @if (_loading)
        {
            <div class="text-center py-4">
                <div class="spinner-border" role="status">
                    <span class="visually-hidden">Loading...</span>
                </div>
            </div>
        }
        else
        {
            @if (!string.IsNullOrEmpty(_message))
            {
                <div class="alert alert-success alert-dismissible fade show">
                    @_message
                    <button type="button" class="btn-close" @onclick="() => _message = null"></button>
                </div>
            }

            <div class="row">
                <div class="col-md-7">
                    <h5 class="mb-3">Theme</h5>
                    <div class="mb-3">
                        @foreach (var theme in new[] { "Light", "Dark", "System" })
                        {
                            <div class="form-check">
                                <input class="form-check-input" type="radio" name="theme" id="@($"theme-{theme}")"
                                       value="@theme" checked="@(_theme == theme)"
                                       @onchange="() => _theme = theme" />
                                <label class="form-check-label" for="@($"theme-{theme}")">@theme</label>
                            </div>
                        }
                    </div>

                    <h5 class="mb-3">Font Size</h5>
                    <div class="mb-3">
                        @foreach (var size in new[] { "Small", "Medium", "Large" })
                        {
                            <div class="form-check form-check-inline">
                                <input class="form-check-input" type="radio" name="fontSize" id="@($"fs-{size}")"
                                       value="@size" checked="@(_fontSize == size)"
                                       @onchange="() => _fontSize = size" />
                                <label class="form-check-label" for="@($"fs-{size}")">@size</label>
                            </div>
                        }
                    </div>

                    <h5 class="mb-3">Language</h5>
                    <div class="mb-3">
                        <select class="form-select" @bind="_language">
                            <option value="en">English</option>
                            <option value="es">Español</option>
                            <option value="fr">Français</option>
                            <option value="de">Deutsch</option>
                            <option value="ja">日本語</option>
                            <option value="zh">中文</option>
                        </select>
                    </div>

                    <h5 class="mb-3">Layout</h5>
                    <div class="mb-3">
                        <div class="form-check form-switch">
                            <input class="form-check-input" type="checkbox" id="compactMode" @bind="_compactMode" />
                            <label class="form-check-label" for="compactMode">Compact Mode</label>
                        </div>
                    </div>

                    <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
                        @if (_saving)
                        {
                            <span class="spinner-border spinner-border-sm me-1"></span>
                        }
                        Save
                    </button>
                </div>

                <div class="col-md-5">
                    <h5 class="mb-3">Preview</h5>
                    <div class="border rounded p-3 @PreviewClasses" style="@PreviewStyle">
                        <div class="@(_compactMode ? "mb-1" : "mb-3")">
                            <strong>Sample Header</strong>
                        </div>
                        <p class="@(_compactMode ? "mb-1" : "mb-2")" style="font-size: @PreviewFontSize">
                            This is how your content will look with the selected settings.
                        </p>
                        <div class="d-flex gap-2">
                            <span class="badge bg-primary">Tag 1</span>
                            <span class="badge bg-secondary">Tag 2</span>
                        </div>
                        <hr class="@(_compactMode ? "my-1" : "my-2")" />
                        <small class="text-muted">Theme: @_theme | Font: @_fontSize | Compact: @(_compactMode ? "On" : "Off")</small>
                    </div>
                </div>
            </div>
        }
    </div>
</div>

@code {
    [Parameter] public ISettingsService SettingsService { get; set; } = default!;

    private bool _loading = true;
    private bool _saving;
    private string? _message;

    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "en";
    private bool _compactMode;

    private string PreviewClasses => _theme switch
    {
        "Dark" => "bg-dark text-light",
        "System" => "bg-body-secondary",
        _ => "bg-white text-dark"
    };

    private string PreviewStyle => $"min-height: 150px; transition: all 0.3s ease;";

    private string PreviewFontSize => _fontSize switch
    {
        "Small" => "0.85rem",
        "Large" => "1.2rem",
        _ => "1rem"
    };

    protected override async Task OnInitializedAsync()
    {
        _loading = true;
        var settings = await SettingsService.GetAppearanceAsync();
        _theme = settings.Theme;
        _fontSize = settings.FontSize;
        _language = settings.Language;
        _compactMode = settings.CompactMode;
        _loading = false;
    }

    private async Task SaveAsync()
    {
        _saving = true;
        var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        _message = "Appearance settings saved!";
        _saving = false;
    }
}
"}

